import java.util.*;

class Solution {
  public boolean canMouseWin(String[] grid, int catJump, int mouseJump) {
    int rows = grid.length, cols = grid[0].length(), cells = rows * cols;
    int mouse = 0, cat = 0, food = 0;
    boolean[] open = new boolean[cells];
    for (int r = 0; r < rows; r++)
      for (int c = 0; c < cols; c++) {
        char ch = grid[r].charAt(c);
        int p = r * cols + c;
        open[p] = ch != '#';
        if (ch == 'M') mouse = p;
        else if (ch == 'C') cat = p;
        else if (ch == 'F') food = p;
      }
    int[][] mouseMoves = moves(open, rows, cols, mouseJump);
    int[][] catMoves = moves(open, rows, cols, catJump);
    // state = (mouse * cells + cat) * 2 + turn, turn 0 = mouse to move; winner: 1 mouse, 2 cat
    byte[] winner = new byte[cells * cells * 2];
    int[] degree = new int[winner.length];
    int[] queue = new int[winner.length];
    int head = 0, tail = 0;
    for (int m = 0; m < cells; m++) {
      if (!open[m]) continue;
      for (int c = 0; c < cells; c++) {
        if (!open[c]) continue;
        int s = (m * cells + c) * 2;
        degree[s] = mouseMoves[m].length;
        degree[s + 1] = catMoves[c].length;
        byte w = 0;
        if (m == c || c == food) w = 2;
        else if (m == food) w = 1;
        if (w != 0) {
          winner[s] = winner[s + 1] = w;
          queue[tail++] = s;
          queue[tail++] = s + 1;
        }
      }
    }
    while (head < tail) {
      int state = queue[head++], turn = state & 1, pair = state >> 1;
      int m = pair / cells, c = pair % cells, result = winner[state];
      // the player who moved into this state is the one who is NOT to move now
      if (turn == 0) {
        for (int pc : catMoves[c]) {
          int prev = (m * cells + pc) * 2 + 1;
          if (winner[prev] != 0) continue;
          if (result == 2 || --degree[prev] == 0) {
            winner[prev] = (byte) (result == 2 ? 2 : 1);
            queue[tail++] = prev;
          }
        }
      } else {
        for (int pm : mouseMoves[m]) {
          int prev = (pm * cells + c) * 2;
          if (winner[prev] != 0) continue;
          if (result == 1 || --degree[prev] == 0) {
            winner[prev] = (byte) (result == 1 ? 1 : 2);
            queue[tail++] = prev;
          }
        }
      }
    }
    return winner[(mouse * cells + cat) * 2] == 1;
  }

  // cells reachable in one turn, including staying put (moves are symmetric, so this also lists
  // the cells a player could have come from)
  private int[][] moves(boolean[] open, int rows, int cols, int jump) {
    int[][] result = new int[rows * cols][];
    int[] dr = {1, -1, 0, 0}, dc = {0, 0, 1, -1};
    int[] buf = new int[1 + 4 * Math.max(rows, cols)];
    for (int p = 0; p < result.length; p++) {
      if (!open[p]) {
        result[p] = new int[0];
        continue;
      }
      int n = 0, r = p / cols, c = p % cols;
      buf[n++] = p;
      for (int d = 0; d < 4; d++)
        for (int step = 1; step <= jump; step++) {
          int nr = r + dr[d] * step, nc = c + dc[d] * step;
          if (nr < 0 || nr >= rows || nc < 0 || nc >= cols || !open[nr * cols + nc]) break;
          buf[n++] = nr * cols + nc;
        }
      result[p] = Arrays.copyOf(buf, n);
    }
    return result;
  }
}
